script:
codepad.commands.register('text-utils.datetime', function () {
  codepad.editor.replaceSelection(new Date().toLocaleString());
});
codepad.commands.register('text-utils.count', function () {
  var t = codepad.editor.getSelectedText() || codepad.editor.getText();
  var words = t.trim() ? t.trim().split(/\s+/).length : 0;
  var lines = t ? t.split('\n').length : 0;
  codepad.window.showMessage(words + ' words, ' + t.length + ' characters, ' + lines + ' lines');
});
codepad.commands.register('text-utils.reverse-lines', function () {
  var t = codepad.editor.getSelectedText();
  if (!t) { codepad.window.showMessage('Select some lines first'); return; }
  codepad.editor.replaceSelection(t.split('\n').reverse().join('\n'));
});
codepad.commands.register('text-utils.quote', function () {
  var t = codepad.editor.getSelectedText();
  if (!t) { codepad.window.showMessage('Select some text first'); return; }
  codepad.editor.replaceSelection(t.split('\n').map(function (l) { return '> ' + l; }).join('\n'));
});
codepad.commands.register('text-utils.prefix', function () {
  codepad.window.showInputBox('Prefix to add to each selected line', function (p) {
    if (p === null) return;
    var t = codepad.editor.getSelectedText();
    if (!t) { codepad.window.showMessage('Select some lines first'); return; }
    codepad.editor.replaceSelection(t.split('\n').map(function (l) { return p + l; }).join('\n'));
  });
});
